function LightIcon({ index }) {
  const variants = [
    <path d="M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1" stroke="currentColor" strokeWidth="1.4" fill="none" strokeLinecap="round"/>,
  ];
  return (
    <svg viewBox="0 0 24 24" width="26" height="26">
      <circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" strokeWidth="1.4" />
      {variants[0]}
    </svg>
  );
}

/* ---------------- Page: PROJECTS --------------- */

function Projects() {
  const [filter, setFilter] = useState("All");
  const [active, setActive] = useState(null);
  const list = filter === "All" ? PROJECTS : PROJECTS.filter((p) => p.cat === filter);

  return (
    <>
      <PageHero
        eyebrow="Project portfolio"
        title="Major GCC developments, built with light"
        text="Royal residences, hospitality landmarks, healthcare, education and commercial towers across the UAE."
        img={IMG.skyCourt}
      />

      <section className="section section-ivory">
        <div className="container">
          <Reveal className="filter-row">
            {PROJECT_FILTERS.map((f) => (
              <button
                key={f}
                className={`filter-chip ${filter === f ? "active" : ""}`}
                onClick={() => setFilter(f)}
              >
                {f}
              </button>
            ))}
          </Reveal>

          <div className="project-grid">
            {list.map((p, i) => (
              <Reveal key={p.name} delay={(i % 6) * 70} className="project-card" >
                <button className="project-card-btn" onClick={() => setActive(p)}>
                  <div className="project-img" style={{ backgroundImage: `url(${p.img})` }} />
                  <div className="project-info">
                    <span className="feature-cat">{p.cat}</span>
                    <h4>{p.name}</h4>
                    <span className="feature-loc">{p.location}</span>
                  </div>
                </button>
              </Reveal>
            ))}
          </div>
        </div>
      </section>

      {active && (
        <div className="lightbox" onClick={() => setActive(null)}>
          <div className="lightbox-panel" onClick={(e) => e.stopPropagation()}>
            <button className="lightbox-close" onClick={() => setActive(null)}>&times;</button>
            <div className="lightbox-img" style={{ backgroundImage: `url(${active.img})` }} />
            <div className="lightbox-body">
              <span className="feature-cat">{active.cat}</span>
              <h3>{active.name}</h3>
              <dl>
                <dt>Location</dt><dd>{active.location}</dd>
                <dt>Client</dt><dd>{active.client}</dd>
                <dt>Consultant</dt><dd>{active.consultant}</dd>
                <dt>Lighting scope</dt><dd>Architectural &amp; interior lighting supply</dd>
              </dl>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

