/* ---------------- Page: CONTACT --------------- */

function Contact() {
  const [sent, setSent] = useState(false);
  const onSubmit = (e) => {
    e.preventDefault();
    setSent(true);
  };
  return (
    <>
      <PageHero
        eyebrow="Contact"
        title="Let's talk about your project"
        text="Reach our team in Dubai, Sharjah, Kuwait or Qatar."
        img={IMG.millLobby}
        short
      />
      <section className="section section-ivory">
        <div className="container split">
          <Reveal className="split-copy">
            <Eyebrow>Send a request</Eyebrow>
            <h2>Request a consultation</h2>
            {sent ? (
              <div className="form-success">Thank you — your request has been noted. Our team will follow up shortly.</div>
            ) : (
              <form className="contact-form" onSubmit={onSubmit}>
                <div className="form-row">
                  <label>Name<input required type="text" placeholder="Your full name" /></label>
                  <label>Company<input type="text" placeholder="Company name" /></label>
                </div>
                <div className="form-row">
                  <label>Email<input required type="email" placeholder="you@company.com" /></label>
                  <label>Phone<input type="tel" placeholder="+971" /></label>
                </div>
                <div className="form-row">
                  <label>Project Type
                    <select defaultValue="">
                      <option value="" disabled>Select a project type</option>
                      <option>Residential</option>
                      <option>Hospitality</option>
                      <option>Commercial / Office</option>
                      <option>Education</option>
                      <option>Healthcare</option>
                      <option>Landscape</option>
                    </select>
                  </label>
                  <label>Location<input type="text" placeholder="City / Emirate" /></label>
                </div>
                <label className="form-full">Message<textarea rows="4" placeholder="Tell us about your project" /></label>
                <button className="btn btn-gold" type="submit">Send Request</button>
              </form>
            )}
          </Reveal>

          <Reveal className="split-copy" delay={120}>
            <Eyebrow>Our locations</Eyebrow>
            <h2>Offices across the GCC</h2>
            <div className="location-list">
              {LOCATIONS.map((l) => (
                <div key={l.city} className="location-item">
                  <span className="location-city">{l.city}</span>
                  <span className="location-note">{l.note}</span>
                </div>
              ))}
            </div>
            <div className="contact-actions">
              <button className="btn btn-line">Download Company Profile</button>
              <button className="btn btn-ghost">WhatsApp Us</button>
            </div>
          </Reveal>
        </div>
      </section>
    </>
  );
}

/* ---------------- Shared: Page hero banner --------------- */

function PageHero({ eyebrow, title, text, img, short }) {
  return (
    <section className={`page-hero ${short ? "short" : ""}`}>
      <div className="page-hero-bg" style={{ backgroundImage: `url(${img})` }} />
      <div className="page-hero-scrim" />
      <div className="page-hero-content">
        <Reveal><Eyebrow>{eyebrow}</Eyebrow></Reveal>
        <Reveal delay={100}><h1>{title}</h1></Reveal>
        {text && <Reveal delay={200}><p>{text}</p></Reveal>}
      </div>
    </section>
  );
}

/* ---------------- App root --------------- */

export default function EuroLightSite() {
  const [page, setPage] = useState("home");
  const [mobileOpen, setMobileOpen] = useState(false);

  const go = useCallback((p) => {
    setPage(p);
    setMobileOpen(false);
    window.scrollTo({ top: 0, behavior: "instant" in window ? "instant" : "auto" });
  }, []);

  let PageComp;
  if (page === "home") PageComp = <Home setPage={go} />;
  else if (page === "about") PageComp = <About setPage={go} />;
  else if (page === "solutions") PageComp = <Solutions setPage={go} />;
  else if (page === "projects") PageComp = <Projects />;
  else if (page === "services") PageComp = <Services setPage={go} />;
  else if (page === "partners") PageComp = <Partners />;
  else if (page === "contact") PageComp = <Contact />;
  else PageComp = <Home setPage={go} />;

  return (
    <div className="el-root">
      <Header page={page} setPage={go} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} />
      <main>{PageComp}</main>
      <Footer setPage={go} />
      <WhatsAppButton />
    </div>
  );
}
